import { useState, useCallback, useRef, useEffect } from "react";

export function useAutoScroll(speed: number = 3) {
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);
  const scrollRef = useRef<number | null>(null);

  const stopAutoScroll = useCallback(() => {
    setIsAutoScrolling(false);
    if (scrollRef.current) {
      cancelAnimationFrame(scrollRef.current);
      scrollRef.current = null;
    }
  }, []);

  const toggleAutoScroll = useCallback(() => {
    if (isAutoScrolling) {
      stopAutoScroll();
    } else {
      setIsAutoScrolling(true);
      const step = () => {
        window.scrollBy({ top: speed, behavior: "auto" });
        scrollRef.current = requestAnimationFrame(step);
      };
      scrollRef.current = requestAnimationFrame(step);
    }
  }, [isAutoScrolling, speed, stopAutoScroll]);

  // Industrial Standard: Stop on user interaction
  useEffect(() => {
    const handleManualInteraction = () => {
      if (isAutoScrolling) stopAutoScroll();
    };

    window.addEventListener("wheel", handleManualInteraction, { passive: true });
    window.addEventListener("touchmove", handleManualInteraction, { passive: true });
    window.addEventListener("mousedown", handleManualInteraction);

    return () => {
      window.removeEventListener("wheel", handleManualInteraction);
      window.removeEventListener("touchmove", handleManualInteraction);
      window.removeEventListener("mousedown", handleManualInteraction);
      if (scrollRef.current) cancelAnimationFrame(scrollRef.current);
    };
  }, [isAutoScrolling, stopAutoScroll]);

  return { isAutoScrolling, toggleAutoScroll, stopAutoScroll };
}