import { Check } from "lucide-react";

const COLOR_MAP: Record<string, string> = {
  Black: "#000000", White: "#ffffff", Blue: "#1d4ed8",
  Grey: "#71717a", Red: "#dc2626", Green: "#15803d", Gold: "#fbbf24", Silver: "#C0C0C0"
};

export function FilterSection({ id, options, selectedOptions, onChange, maxPriceLimit }: any) {
  const isPrice = id === "priceRange";
  const isColor = id === "color";
  const maxVal = isPrice ? (selectedOptions[0] || `0-${maxPriceLimit}`).split("-")[1] : maxPriceLimit;

  return (
    <div className="pt-2 pb-4">
      {isPrice ? (
        <div className="px-2">
          <div className="flex justify-between mb-4">
            <span className="text-[10px] font-black uppercase">₹0</span>
            <span className="text-[10px] font-black text-brand bg-brand/5 px-2 py-1 rounded-full">
              Under ₹{Number(maxVal).toLocaleString()}
            </span>
          </div>
          <input
            type="range" min="0" max={maxPriceLimit} step="500"
            value={maxVal}
            onChange={(e) => onChange(id, `0-${e.target.value}`, true)}
            className="w-full h-1 bg-border rounded-full appearance-none cursor-pointer accent-brand"
          />
        </div>
      ) : (
        <div className={`flex flex-wrap gap-${isColor ? '3' : '2'}`}>
          {options.map((opt: string) => (
            <button
              key={opt}
              onClick={() => onChange(id, opt, false)}
              className={isColor 
                ? `w-9 h-9 rounded-full border-2 flex items-center justify-center transition-all ${selectedOptions.includes(opt) ? "border-brand scale-110 shadow-lg" : "border-border"}`
                : `px-4 py-2.5 rounded-full border text-[10px] font-black uppercase tracking-widest transition-all ${selectedOptions.includes(opt) ? "bg-foreground text-background border-foreground shadow-lg scale-95" : "bg-background border-border"}`
              }
              style={isColor ? { backgroundColor: COLOR_MAP[opt] || "#ccc" } : {}}
            >
              {isColor && selectedOptions.includes(opt) && (
                <Check size={16} className={opt === "White" ? "text-black" : "text-white"} />
              )}
              {!isColor && opt}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}