import { useState, useMemo, useEffect } from "react";
import { Product } from "@/data/store-data";

export function useCatalogue(initialProducts: Product[]) {
  const [activeFilters, setActiveFilters] = useState<Record<string, string[]>>({});
  const [sortBy, setSortBy] = useState("newest");

  // 1. Calculate dynamic price limit based on the current product set
  const maxPriceLimit = useMemo(() => {
    if (initialProducts.length === 0) return 30000;
    return Math.ceil(Math.max(...initialProducts.map((p) => p.price)) / 1000) * 1000;
  }, [initialProducts]);

  // 2. Initialize price filter when data loads
  useEffect(() => {
    setActiveFilters((prev) => ({
      ...prev,
      priceRange: [`0-${maxPriceLimit}`],
    }));
  }, [maxPriceLimit]);

  // 3. Core Filtering Logic
  const filteredProducts = useMemo(() => {
    let result = initialProducts.filter((product) => {
      for (const [key, values] of Object.entries(activeFilters)) {
        if (!values || values.length === 0) continue;

        if (key === "priceRange") {
          const [min, max] = values[0].split("-").map(Number);
          if (product.price < min || product.price > max) return false;
          continue;
        }

        const productValue = (product as any)[key]?.toString().toLowerCase();
        const matches = values.some((v) => v.toLowerCase() === productValue);
        if (!matches) return false;
      }
      return true;
    });

    // 4. Sorting Logic
    const strategies: Record<string, (a: Product, b: Product) => number> = {
      "price-asc": (a, b) => a.price - b.price,
      "price-desc": (a, b) => b.price - a.price,
      "most-sold": (a, b) => (b.salesCount || 0) - (a.salesCount || 0),
      "newest": (a, b) => b.staticNumber - a.staticNumber,
    };

    return strategies[sortBy] ? [...result].sort(strategies[sortBy]) : result;
  }, [initialProducts, activeFilters, sortBy]);

  return {
    filteredProducts,
    activeFilters,
    setActiveFilters,
    sortBy,
    setSortBy,
    maxPriceLimit,
  };
}