"use client";

import { useState, useMemo, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { SlidersHorizontal, ArrowUpDown, Play, Square, X, ChevronDown } from "lucide-react";

// Feature Imports
import { useCatalogue, useAutoScroll, FilterSection } from "@/features/product-catalogue";

// Shared/UI Imports
import { MOCK_PRODUCTS } from "@/data/store-data";
import brandLogos from "@/data/brandLogos";
import { StoreProductCard } from "@/components/ui/cards/StoreProductCard";
import { useSettings } from "@/context/SettingsContext";

export default function BrandClient({ brandSlug }: { brandSlug: string }) {
  const { settings } = useSettings();
  const [activeDrawer, setActiveDrawer] = useState<"filter" | "sort" | null>(null);
  const [openSections, setOpenSections] = useState<Record<string, boolean>>({ priceRange: true });

  // 1. Data Context
  const baseProducts = useMemo(() => {
    if (!brandSlug) return [];
    return MOCK_PRODUCTS.filter(p => p?.brand?.toLowerCase() === brandSlug.toLowerCase());
  }, [brandSlug]);

  const brandInfo = useMemo(() => {
    if (!brandSlug) return null;
    return brandLogos.find(b => b.name.toLowerCase() === brandSlug.toLowerCase());
  }, [brandSlug]);

  // 2. Logic Hooks
  const { 
    filteredProducts, activeFilters, setActiveFilters, 
    sortBy, setSortBy, maxPriceLimit 
  } = useCatalogue(baseProducts);
  
  const { isAutoScrolling, toggleAutoScroll } = useAutoScroll(settings?.autoScrollLevel);

  // 3. Staged Mobile State
  const [stagedFilters, setStagedFilters] = useState(activeFilters);
  useEffect(() => {
    if (activeDrawer === "filter") setStagedFilters(activeFilters);
  }, [activeDrawer, activeFilters]);

  const filterConfigs = useMemo(() => [
    { id: "priceRange", label: "Budget", options: [] },
    { id: "category", label: "Categories", options: Array.from(new Set(baseProducts.map(p => p.category))) },
    { id: "color", label: "Colors", options: Array.from(new Set(baseProducts.map(p => p.color).filter(Boolean))) },
  ], [baseProducts]);

  const handleFilterUpdate = (id: string, opt: string, isRange: boolean) => {
    const target = activeDrawer === "filter" ? setStagedFilters : setActiveFilters;
    target(prev => {
      const cur = prev[id] || [];
      if (isRange) return { ...prev, [id]: [opt] };
      return cur.includes(opt) ? { ...prev, [id]: cur.filter(i => i !== opt) } : { ...prev, [id]: [...cur, opt] };
    });
  };

  return (
    <div className="bg-background min-h-screen text-foreground">
      {/* HEADER */}
      <header className="pt-32 pb-16 px-4 border-b border-border text-center">
        {brandInfo?.logo && (
          <motion.img 
            initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}
            src={brandInfo.logo} alt="" className="h-12 mx-auto mb-8 dark:invert opacity-80" 
          />
        )}
        <h1 className="text-5xl md:text-7xl font-black italic tracking-tighter uppercase leading-none">
          {brandSlug}<span className="text-brand">.</span>
        </h1>
      </header>

      {/* MOBILE TOOLBAR */}
      <div className="sticky lg:hidden top-16 z-30 bg-background border-b border-border flex h-12">
        <button onClick={() => setActiveDrawer("filter")} className="flex-1 flex items-center justify-center gap-2 text-[10px] font-black uppercase border-r border-border">
          <SlidersHorizontal size={13} /> Filter
        </button>
        <button onClick={toggleAutoScroll} className={`flex-1 flex items-center justify-center gap-2 text-[10px] font-black uppercase border-r border-border ${isAutoScrolling ? 'text-brand' : ''}`}>
          {isAutoScrolling ? <Square size={12} fill="currentColor" /> : <Play size={12} fill="currentColor" />} Scroll
        </button>
        <button onClick={() => setActiveDrawer("sort")} className="flex-1 flex items-center justify-center gap-2 text-[10px] font-black uppercase">
          <ArrowUpDown size={13} /> Sort
        </button>
      </div>

      <main className="container mx-auto flex gap-12 py-12 px-4">
        {/* SIDEBAR */}
        <aside className="hidden lg:block w-72 shrink-0 sticky top-28 h-fit">
          <button onClick={toggleAutoScroll} className={`w-full py-4 rounded-full border mb-8 flex items-center justify-center gap-3 transition-all ${isAutoScrolling ? 'bg-brand border-brand text-white' : 'border-border'}`}>
             {isAutoScrolling ? <Square size={12} fill="currentColor" /> : <Play size={12} fill="currentColor" />}
             <span className="text-[11px] font-black uppercase tracking-widest">Auto Scroll</span>
          </button>

          {filterConfigs.map(config => (
            <div key={config.id} className="border-b border-border py-4">
              <button onClick={() => setOpenSections(p => ({ ...p, [config.id]: !p[config.id] }))} className="flex w-full items-center justify-between text-[11px] font-black uppercase py-2">
                {config.label} <ChevronDown className={openSections[config.id] ? "rotate-180" : ""} />
              </button>
              {openSections[config.id] && (
                <FilterSection {...config} selectedOptions={activeFilters[config.id] || []} onChange={handleFilterUpdate} maxPriceLimit={maxPriceLimit} />
              )}
            </div>
          ))}
        </aside>

        {/* PRODUCT GRID */}
        <div className="flex-1">
          <div className="grid grid-cols-2 xl:grid-cols-3 gap-x-4 gap-y-12">
            <AnimatePresence mode="popLayout">
              {filteredProducts.map(p => (
                <motion.div key={p.id} layout initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                  <StoreProductCard product={p} />
                </motion.div>
              ))}
            </AnimatePresence>
          </div>
        </div>
      </main>

      {/* MOBILE DRAWER */}
      <AnimatePresence>
        {activeDrawer && (
          <>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setActiveDrawer(null)} className="fixed inset-0 z-[60] bg-black/40 backdrop-blur-sm" />
            <motion.div initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }} transition={{ type: "spring", damping: 25, stiffness: 200 }} className="fixed bottom-0 left-0 right-0 z-[70] bg-background rounded-t-[2rem] max-h-[90vh] flex flex-col">
              <div className="p-6 overflow-y-auto">
                <div className="flex justify-between items-center mb-8">
                  <h2 className="text-xl font-black uppercase italic">Refine</h2>
                  <button onClick={() => setActiveDrawer(null)}><X /></button>
                </div>

                {activeDrawer === "filter" ? (
                  <div className="space-y-8">
                    {filterConfigs.map(config => (
                      <div key={config.id}>
                        <p className="text-[10px] font-black uppercase opacity-40 mb-4">{config.label}</p>
                        <FilterSection {...config} selectedOptions={stagedFilters[config.id] || []} onChange={handleFilterUpdate} maxPriceLimit={maxPriceLimit} />
                      </div>
                    ))}
                    <button 
                      onClick={() => { setActiveFilters(stagedFilters); setActiveDrawer(null); }}
                      className="w-full py-5 bg-brand text-white rounded-full font-black uppercase text-[12px] mt-4"
                    >
                      Apply Filters ({filteredProducts.length} Items)
                    </button>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {["newest", "most-sold", "price-asc", "price-desc"].map((opt) => (
                      <button 
                        key={opt} 
                        onClick={() => { setSortBy(opt); setActiveDrawer(null); }}
                        className={`w-full py-5 text-left text-[12px] font-black uppercase border-b border-border/50 ${sortBy === opt ? 'text-brand' : 'opacity-60'}`}
                      >
                        {opt.replace('-', ' ')}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </div>
  );
}